import { chromium } from "playwright-core";
import { pathToFileURL } from "node:url";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const usability = path.join(root, "usability");
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

const freezeSpinners = `
  const style = document.createElement("style");
  style.textContent = ".button-spinner, .params-spinner { animation: none !important; transform: rotate(40deg); }";
  document.head.appendChild(style);
`;

const loadingState = `
  ${freezeSpinners}
  const dropHint = document.getElementById("dropHint");
  const hud = document.getElementById("traceLoadingHud");
  const uploadStatus = document.getElementById("uploadStatus");
  const paramsBar = document.getElementById("paramsBar");
  const canvas = document.getElementById("canvas");
  const playbackBar = document.getElementById("playbackBar");
  const playbackToggle = document.getElementById("playbackToggle");
  const mobileTransport = document.getElementById("mobileTransport");
  if (dropHint) dropHint.style.display = "none";
  if (canvas) canvas.classList.remove("has-trace");
  document.body.classList.add("trace-loaded-mobile", "trace-loading");
  document.body.classList.remove("playback-ready", "trace-loading-error");
  if (playbackBar) playbackBar.classList.remove("visible");
  if (playbackToggle) playbackToggle.classList.remove("visible");
  if (mobileTransport) {
    mobileTransport.classList.remove("visible");
    mobileTransport.setAttribute("aria-hidden", "true");
    for (const btn of mobileTransport.querySelectorAll("button")) btn.disabled = true;
  }
  if (hud) {
    hud.classList.add("visible");
    hud.setAttribute("aria-hidden", "false");
  }
  if (uploadStatus) {
    uploadStatus.className = "sub upload-status-loading";
    uploadStatus.innerHTML = '<span class="button-spinner" aria-hidden="true"></span><span>Computing trace…</span>';
  }
  if (paramsBar) {
    paramsBar.innerHTML = \`
      <span class="params-metric params-metric--blue params-metric--frechet"><span class="params-metric-body"><span class="params-metric-label">Computed Fréchet distance</span><span class="params-metric-value params-metric-value--loading" aria-live="polite"><span class="button-spinner params-spinner" aria-hidden="true"></span><span class="visually-hidden">Loading</span></span></span></span>
      <span class="params-metric params-metric--blue params-metric--time"><span class="params-metric-body"><span class="params-metric-label">Simplification time</span><span class="params-metric-value params-metric-value--loading" aria-live="polite"><span class="button-spinner params-spinner" aria-hidden="true"></span><span class="visually-hidden">Loading</span></span></span></span>
    \`;
  }
`;

function measureDock() {
  const dock = document.getElementById("mobileTransport");
  const hud = document.getElementById("traceLoadingHud");
  const canvasWrap = document.getElementById("canvasWrap");
  const cs = dock ? getComputedStyle(dock) : null;
  const wrap = canvasWrap ? getComputedStyle(canvasWrap) : null;
  return {
    innerWidth: window.innerWidth,
    scrollWidth: document.documentElement.scrollWidth,
    bodyClasses: document.body.className,
    dockDisplay: cs ? cs.display : null,
    dockAriaHidden: dock ? dock.getAttribute("aria-hidden") : null,
    dockHasVisible: dock ? dock.classList.contains("visible") : null,
    dockRect: dock ? dock.getBoundingClientRect().toJSON() : null,
    hudDisplay: hud ? getComputedStyle(hud).display : null,
    canvasPaddingBottom: wrap ? wrap.paddingBottom : null,
  };
}

const browser = await chromium.launch({ executablePath: chrome, headless: true });

const fixturePage = await browser.newPage({ viewport: { width: 430, height: 1180 }, deviceScaleFactor: 1 });
await fixturePage.goto(pathToFileURL(path.join(usability, "mobile-playback-dock-loading.html")).href, { waitUntil: "load" });
await fixturePage.screenshot({
  path: path.join(usability, "mobile-playback-dock-loading.png"),
  fullPage: true,
});
await fixturePage.close();

const live = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
await live.goto(pathToFileURL(path.join(root, "index.html")).href, { waitUntil: "domcontentloaded" });
await live.evaluate(loadingState);
const loadingMetrics = await live.evaluate(measureDock);
await live.screenshot({
  path: path.join(usability, "mobile-playback-dock-loading-live.png"),
});

await live.evaluate(() => {
  const canvas = document.getElementById("canvas");
  const hud = document.getElementById("traceLoadingHud");
  const mobileTransport = document.getElementById("mobileTransport");
  document.body.classList.add("playback-ready");
  document.body.classList.remove("trace-loading");
  if (canvas) canvas.classList.add("has-trace");
  if (hud) {
    hud.classList.remove("visible");
    hud.setAttribute("aria-hidden", "true");
  }
  if (mobileTransport) {
    mobileTransport.classList.add("visible");
    mobileTransport.setAttribute("aria-hidden", "false");
    for (const btn of mobileTransport.querySelectorAll("button")) btn.disabled = false;
  }
});
const readyMetrics = await live.evaluate(measureDock);
await live.close();

const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
await desktop.goto(pathToFileURL(path.join(root, "index.html")).href, { waitUntil: "domcontentloaded" });
await desktop.evaluate(loadingState);
const desktopLoading = await desktop.evaluate(() => {
  const bar = document.getElementById("playbackBar");
  const cs = bar ? getComputedStyle(bar) : null;
  return {
    innerWidth: window.innerWidth,
    playbackDisplay: cs ? cs.display : null,
    playbackVisibleClass: bar ? bar.classList.contains("visible") : null,
    hudDisplay: getComputedStyle(document.getElementById("traceLoadingHud")).display,
  };
});
await desktop.close();

await browser.close();
console.log(JSON.stringify({ loadingMetrics, readyMetrics, desktopLoading }, null, 2));

import { chromium } from "playwright-core";
import { pathToFileURL } from "node:url";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const out = "/tmp/pwshot";

const freezeSpinners = `
  const style = document.createElement("style");
  style.textContent = ".button-spinner, .params-spinner { animation: none !important; transform: rotate(40deg); }";
  document.head.appendChild(style);
`;

const loadingState = `
  ${freezeSpinners}
  const dropHint = document.getElementById("dropHint");
  const hud = document.getElementById("traceLoadingHud");
  const uploadStatus = document.getElementById("uploadStatus");
  const paramsBar = document.getElementById("paramsBar");
  const canvas = document.getElementById("canvas");
  const playbackBar = document.getElementById("playbackBar");
  const playbackToggle = document.getElementById("playbackToggle");
  const mobileTransport = document.getElementById("mobileTransport");
  const sidebar = document.getElementById("sidebar");
  if (dropHint) dropHint.style.display = "none";
  if (canvas) canvas.classList.remove("has-trace");
  document.body.classList.add("trace-loaded-mobile", "trace-loading");
  document.body.classList.remove("playback-ready", "trace-loading-error");
  if (sidebar) sidebar.style.display = "flex";
  if (playbackBar) playbackBar.classList.remove("visible");
  if (playbackToggle) playbackToggle.classList.remove("visible");
  if (mobileTransport) {
    mobileTransport.classList.remove("visible");
    mobileTransport.setAttribute("aria-hidden", "true");
  }
  if (hud) {
    hud.classList.add("visible");
    hud.setAttribute("aria-hidden", "false");
  }
  if (uploadStatus) {
    uploadStatus.className = "sub upload-status-loading";
    uploadStatus.innerHTML = '<span class="button-spinner" aria-hidden="true"></span><span>Computing trace…</span>';
  }
  if (paramsBar) {
    paramsBar.innerHTML = \`
      <span class="params-metric params-metric--blue params-metric--frechet"><span class="params-metric-body"><span class="params-metric-label">Computed Fréchet distance</span><span class="params-metric-value params-metric-value--loading"><span class="button-spinner params-spinner"></span></span></span></span>
      <span class="params-metric params-metric--blue params-metric--time"><span class="params-metric-body"><span class="params-metric-label">Simplification time</span><span class="params-metric-value params-metric-value--loading"><span class="button-spinner params-spinner"></span></span></span></span>
    \`;
  }
  const statusIndices = document.getElementById("statusIndices");
  const statusGrid = document.getElementById("statusGrid");
  if (statusIndices) {
    statusIndices.innerHTML = '<div class="status-idx-block"><span class="idx-label" style="color:#ff9f43">p (start)</span><span class="idx-num" style="color:#ff9f43">#0</span></div><div class="status-idx-block"><span class="idx-label" style="color:#ff7ae8">v_i (current)</span><span class="idx-num" style="color:#ff7ae8">#1</span></div>';
  }
  if (statusGrid) {
    statusGrid.innerHTML = '<span>step</span><span class="mono"><b>1</b></span><span>alive</span><span class="mono"><b>…</b></span>';
  }
`;

function scan() {
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const overflow = document.documentElement.scrollWidth > vw + 1;
  const offenders = [];
  const nodes = document.body.querySelectorAll("*");
  for (const el of nodes) {
    const r = el.getBoundingClientRect();
    if (r.width < 2 && r.height < 2) continue;
    const cs = getComputedStyle(el);
    if (cs.display === "none" || cs.visibility === "hidden") continue;
    if (r.right > vw + 1 || r.left < -1) {
      offenders.push({
        id: el.id || el.className,
        tag: el.tagName,
        left: Math.round(r.left),
        right: Math.round(r.right),
        w: Math.round(r.width),
      });
    }
  }
  const sidebar = document.getElementById("sidebar");
  const canvas = document.getElementById("canvasContainer");
  const hud = document.getElementById("traceLoadingHud");
  const dock = document.getElementById("mobileTransport");
  const play = document.getElementById("mobilePlayBtn");
  const drop = document.getElementById("dropHint");
  return {
    vw, vh,
    scrollWidth: document.documentElement.scrollWidth,
    scrollHeight: document.documentElement.scrollHeight,
    overflow,
    overflowOffenders: offenders.slice(0, 12),
    body: document.body.className,
    sidebarDisplay: sidebar ? getComputedStyle(sidebar).display : null,
    sidebarRect: sidebar ? sidebar.getBoundingClientRect().toJSON() : null,
    canvasRect: canvas ? canvas.getBoundingClientRect().toJSON() : null,
    hudDisplay: hud ? getComputedStyle(hud).display : null,
    dockDisplay: dock ? getComputedStyle(dock).display : null,
    playDisabled: play ? play.disabled : null,
    dropDisplay: drop ? getComputedStyle(drop).display : null,
  };
}

const browser = await chromium.launch({ executablePath: chrome, headless: true });

const mobileStart = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
await mobileStart.goto(pathToFileURL(path.join(root, "index.html")).href, { waitUntil: "domcontentloaded" });
const startScan = await mobileStart.evaluate(scan);
await mobileStart.screenshot({ path: path.join(out, "scan-mobile-start.png"), fullPage: true });
await mobileStart.close();

const mobileLoad = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
await mobileLoad.goto(pathToFileURL(path.join(root, "index.html")).href, { waitUntil: "domcontentloaded" });
await mobileLoad.evaluate(loadingState);
const loadScan = await mobileLoad.evaluate(scan);
await mobileLoad.screenshot({ path: path.join(out, "scan-mobile-loading-full.png"), fullPage: true });
await mobileLoad.close();

const desktopEmpty = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
await desktopEmpty.goto(pathToFileURL(path.join(root, "index.html")).href, { waitUntil: "domcontentloaded" });
const emptyScan = await desktopEmpty.evaluate(scan);
await desktopEmpty.screenshot({ path: path.join(out, "scan-desktop-empty.png") });
await desktopEmpty.close();

const desktopLoad = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
await desktopLoad.goto(pathToFileURL(path.join(root, "index.html")).href, { waitUntil: "domcontentloaded" });
await desktopLoad.evaluate(loadingState);
const deskLoadScan = await desktopLoad.evaluate(scan);
await desktopLoad.screenshot({ path: path.join(out, "scan-desktop-loading.png") });
await desktopLoad.close();

await browser.close();
console.log(JSON.stringify({ startScan, loadScan, emptyScan, deskLoadScan }, null, 2));
